<div class="row g-3 mb-4"><?php foreach ($report['rows'] as $row): ?><div class="col-md-6"><article class="feature-card h-100"><h3 class="h5">Rp<?php echo number_format((int) $row['amount_idr'], 0, ',', '.'); ?></h3><?php if ($admin_list): ?><p class="text-break"><?php echo html_escape($row['display_name']); ?></p><?php endif; ?><p><?php echo html_escape(study_donation_status($row['status'])); ?><?php if ($row['review_required']): ?> <span class="badge text-bg-warning">Refund/sengketa: perlu ditinjau</span><?php endif; ?></p><p class="small text-secondary"><?php echo html_escape(study_format_datetime($row['created_at'])); ?></p><a class="btn btn-outline-primary" href="<?php echo site_url('donasi/pesanan/'.(int) $row['id']).'?environment='.html_escape($environment); ?>">Lihat QRIS & status</a></article></div><?php endforeach; ?></div>
<?php if ( ! $report['rows']): ?><p>Belum ada donasi pada lingkungan/filter ini.</p><?php endif; ?>
<nav class="d-flex flex-wrap align-items-center gap-3" aria-label="Halaman donasi"><?php $base = $admin_list ? 'kelola/donasi' : 'donasi'; $query = array('environment' => $environment, 'status' => $status); ?><?php if ($page > 1): ?><a class="btn btn-outline-secondary" href="<?php echo html_escape(site_url($base).'?'.http_build_query($query + array('halaman' => $page - 1))); ?>">Sebelumnya</a><?php endif; ?><span>Halaman <?php echo (int) $page; ?> · <?php echo (int) $report['summary']['total']; ?> pesanan</span><?php if ($page * 20 < (int) $report['summary']['total']): ?><a class="btn btn-outline-primary" href="<?php echo html_escape(site_url($base).'?'.http_build_query($query + array('halaman' => $page + 1))); ?>">Berikutnya</a><?php endif; ?></nav>
